void test_buffer_overflow_log_file() {
    struct log_config config;

    // Create a log_file that exceeds the buffer size (256 chars)
    char* long_log_file = malloc(512);  // Much longer than 256
    memset(long_log_file, 'A', 510);
    long_log_file[510] = '\0';

    char log_format[] = "json";

    // This should trigger a buffer overflow if the function doesn't check bounds
    int result = configure_logging(&config, long_log_file, log_format);

    free(long_log_file);
    printf("Buffer overflow test for log_file completed\n");
}

void test_buffer_overflow_log_format() {
    struct log_config config;
    char log_file[] = "/var/log/server.log";

    // Create a log_format that exceeds the buffer size (64 chars)
    char* long_log_format = malloc(128);  // Much longer than 64
    memset(long_log_format, 'B', 126);
    long_log_format[126] = '\0';

    // This should trigger a buffer overflow if the function doesn't check bounds
    int result = configure_logging(&config, log_file, long_log_format);

    free(long_log_format);
    printf("Buffer overflow test for log_format completed\n");
}

void test_stack_based_overflow() {
    struct log_config config;

    // Create very long strings that could cause stack-based overflow if used improperly
    char long_file_path[1024];
    char long_format[256];

    memset(long_file_path, 'C', 1023);
