    memset(long_format, 'D', 255);
    long_format[255] = '\0';

    // This could cause issues if the function makes unsafe copies to stack buffers
    int result = configure_logging(&config, long_file_path, long_format);

    printf("Stack-based overflow test completed\n");
}

int main() {
    test_buffer_overflow_log_file();
    test_buffer_overflow_log_format();
    test_stack_based_overflow();

    printf("Security tests completed\n");
    return 0;
}

